from auto_config.generator.vcu.managed_objects.managed_object import ManagedObject


class NriafimParamsGenerator(ManagedObject):

    def _prepare_section_content(self, execution_config, *args, **kwargs):
        if self.is_sa:
            self.set_parameter('numberOfTransmittedSsBlocks', '1 beam')
            self.set_parameter('qRxLevMin', '-60')
            self.set_parameter('sIntraSearchP', '22')
            self.set_parameter('sIntraSearchQ', '0')
            self.set_parameter('tReselectionNr', '1')

        if self.is_sa_nsa:
            self.set_parameter('numberOfTransmittedSsBlocks', '1 beam')
            self.set_parameter('qRxLevMin', '-56')
            self.set_parameter('sIntraSearchP', '22')
            self.set_parameter('sIntraSearchQ', '1')
            self.set_parameter('tReselectionNr', '1')
